&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; style=&quot;text-align: justify;&quot; data-block=&quot;true&quot; data-editor=&quot;51ou4&quot; data-offset-key=&quot;btevm-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;btevm-0-0&quot;&gt;&lt;span data-offset-key=&quot;btevm-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Direct engineers on your team through complex, multi-quarter projects: break down the architecture, assign the work, and own the outcome even when the execution is distributed.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; style=&quot;text-align: justify;&quot; data-block=&quot;true&quot; data-editor=&quot;51ou4&quot; data-offset-key=&quot;6ihuo-0-0&quot;&gt;
